import io
import json
import os
import urllib.error
from email.message import Message
from unittest.mock import patch

import openai_client


class Response:
    status = 200
    headers = {\"x-request-id\": \"req_test\"}

    def __init__(self, payload):
        self.payload = payload

    def __enter__(self):
        return self

    def __exit__(self, *args):
        return False

    def read(self):
        return json.dumps(self.payload).encode()

    def getcode(self):
        return self.status


sample = {
    \"id\": \"resp_1\",
    \"output\": [
        {
            \"type\": \"message\",
            \"content\": [{\"type\": \"output_text\", \"text\": \"Hello\"}],
        }
    ],
}
with patch.dict(
    os.environ,
    {\"OPENAI_API_KEY\": \"sk-test\", \"OPENAI_MODEL\": \"test-model\"},
    clear=True,
):
    with patch(\"urllib.request.urlopen\", return_value=Response(sample)) as mocked:
        result = openai_client.send_prompt(\"Private prompt\")
        assert openai_client.extract_text(result) == \"Hello\"
        request = mocked.call_args.args[0]
        assert json.loads(request.data) == {
            \"model\": \"test-model\",
            \"input\": \"Private prompt\",
            \"store\": False,
        }
        assert request.full_url == \"https://api.openai.com/v1/responses\"
        assert request.get_header(\"Authorization\") == \"Bearer sk-test\"

headers = Message()
headers[\"x-request-id\"] = \"req_error\"
error_payload = json.dumps(
    {\"error\": {\"message\": \"Invalid input: Private prompt\", \"type\": \"invalid_request_error\"}}
).encode()
http_error = urllib.error.HTTPError(
    \"https://api.openai.com/v1/responses\", 400, \"Bad Request\", headers, io.BytesIO(error_payload)
)
try:
    raise openai_client.OpenAIClient._http_error(http_error, \"Private prompt\")
except openai_client.OpenAIResponseError as error:
    assert \"Private prompt\" not in str(error)
    assert \"[prompt]\" in str(error)
    assert error.status_code == 400
    assert error.request_id == \"req_error\"

for base_url in (\"http://example.com\", \"https://user:pass@example.com\"):
    try:
        openai_client.OpenAIClient(api_key=\"key\", model=\"model\", base_url=base_url)
    except ValueError:
        pass
    else:
        raise AssertionError(\"unsafe base URL accepted: \" + base_url)

try:
    openai_client.OpenAIClient()
except openai_client.OpenAIRequestError:
    pass
else:
    raise AssertionError(\"missing API key accepted\")

try:
    openai_client.extract_text({})
except Exception:
    raise AssertionError(\"extract_text should be total\")

print(\"focused checks passed\")
